import { registerBlockType } from '@wordpress/blocks';
import { useBlockProps } from '@wordpress/block-editor';

registerBlockType('fixture/counter', {
	edit() {
		const blockProps = useBlockProps();
		return (
			<div {...blockProps}>
				<button type="button" aria-label="Decrement">−</button>
				<span className="count">0</span>
				<button type="button" aria-label="Increment">+</button>
			</div>
		);
	},
	save() {
		// Dynamic block: markup is generated by render.php on the server.
		// Returning null tells WP not to store any HTML in post content.
		return null;
	},
});
